!function(){function t(t){return function(t){if(Array.isArray(t))return r(t)}(t)||function(t){if("undefined"!=typeof Symbol&&null!=t[Symbol.iterator]||null!=t["@@iterator"])return Array.from(t)}(t)||function(t,s){if(t){if("string"==typeof t)return r(t,s);var e={}.toString.call(t).slice(8,-1);return"Object"===e&&t.constructor&&(e=t.constructor.name),"Map"===e||"Set"===e?Array.from(t):"Arguments"===e||/^(?:Ui|I)nt(?:8|16|32)(?:Clamped)?Array$/.test(e)?r(t,s):void 0}}(t)||function(){throw new TypeError("Invalid attempt to spread non-iterable instance.\nIn order to be iterable, non-array objects must have a [Symbol.iterator]() method.")}()}function r(t,r){(null==r||r>t.length)&&(r=t.length);for(var s=0,e=Array(r);s<r;s++)e[s]=t[s];return e}System.register(["./index-legacy-DFVKc2pa.js"],function(r,s){"use strict";var e,a,o,l;return{setters:[function(t){e=t._,a=t.o,o=t.c,l=t.a}],execute:function(){var s={class:"max-w-4xl mx-auto px-4 py-8"};r("default",e({},[["render",function(r,e){return a(),o("article",s,t(e[0]||(e[0]=[l('<h1 class="text-2xl font-bold text-gray-800 mb-4"> GARGANTUA 超大质量黑洞光线追踪可视化工具 — 在线实时史瓦西黑洞吸积盘渲染器 </h1><p class="text-gray-600 leading-relaxed mb-6"> GARGANTUA 是一个基于 WebGL 的史瓦西度规（Schwarzschild metric）零测地线光线追踪（null-geodesic raytracing）可视化工具。它模拟了超大质量黑洞周围的光线弯曲效应、引力透镜（gravitational lensing）、相对论性吸积盘辐射，以及多普勒频移和引力红移等物理现象。所有渲染在浏览器端通过 GPU 并行计算完成，无需上传数据到服务器。 </p><section class="mb-8"><h2 class="text-xl font-semibold text-gray-800 mb-3">核心物理模型</h2><p class="text-gray-600 leading-relaxed mb-3"> 本工具采用几何单位制（c = G = 1），以史瓦西半径 RS = 1.0 为基准长度单位。每像素发射一条光子，沿 Schwarzschild 时空中积分零测地线方程，步长根据距中心距离自适应调整：靠近黑洞事件视界处使用更小的积分步长以确保精度。 </p><ul class="list-disc list-inside text-gray-600 space-y-1 ml-4"><li>零测地线数值积分：最多 600 步/像素，支持三档质量等级（Standard 200 / High 320 / Cinematic 460 步）</li><li>Novikov-Thorne 吸积盘通量模型：基于 ISCO（最内稳定圆轨道，3 RS）的薄盘辐射分布</li><li>黑体谱温度映射 + 相对论多普勒增亮 + 引力红移修正</li><li>FBM 噪声驱动的湍流纹理，含切向条纹和暗带结构</li><li>程序化银河系背景 + 四层哈希星空分布</li></ul></section><section class="mb-8"><h2 class="text-xl font-semibold text-gray-800 mb-3">交互功能</h2><div class="grid grid-cols-1 md:grid-cols-2 gap-6"><div class="bg-gray-50 rounded-lg p-4"><h3 class="font-medium text-gray-800 mb-2">相机控制</h3><ul class="text-sm text-gray-600 space-y-1 list-disc list-inside"><li><strong>拖拽</strong> — 轨道旋转视角</li><li><strong>滚轮/捏合</strong> — 缩放距离</li><li><strong>自动轨道</strong> — 持续环绕旋转</li><li><strong>电影序列</strong> — Catmull-Rom 样条插值的 8 关键帧闭环飞行路径</li></ul></div><div class="bg-gray-50 rounded-lg p-4"><h3 class="font-medium text-gray-800 mb-2">预设视角</h3><ul class="text-sm text-gray-600 space-y-1 list-disc list-inside"><li><strong>POSTER 38°</strong> — 海报级经典视角</li><li><strong>EDGE-ON</strong> — 盘面边缘对齐视角，展现最大引力透镜弧</li><li><strong>POLAR</strong> — 极区俯视，观察吸积盘完整环状结构</li><li><strong>CLOSE PASS</strong> — 近距离掠过，体验强引力场畸变</li></ul></div></div></section><section class="mb-8"><h2 class="text-xl font-semibold text-gray-800 mb-3">可调参数</h2><p class="text-gray-600 leading-relaxed mb-3"> 点击界面右下角的 PARAMS 按钮打开参数面板，可实时调整以下物理和渲染参数： </p><div class="overflow-x-auto"><table class="w-full text-sm text-left border-collapse"><thead><tr class="bg-gray-100"><th class="px-3 py-2 border border-gray-200">参数</th><th class="px-3 py-2 border border-gray-200">说明</th><th class="px-3 py-2 border border-gray-200">范围</th></tr></thead><tbody><tr><td class="px-3 py-2 border border-gray-200 font-mono text-xs">GEODESIC STEPS</td><td class="px-3 py-2 border border-gray-200">光线追踪积分步数</td><td class="px-3 py-2 border border-gray-200">60–600</td></tr><tr><td class="px-3 py-2 border border-gray-200 font-mono text-xs">DISK INNER EDGE</td><td class="px-3 py-2 border border-gray-200">吸积盘内边缘半径</td><td class="px-3 py-2 border border-gray-200">2.0–4.0 RS</td></tr><tr><td class="px-3 py-2 border border-gray-200 font-mono text-xs">DISK OUTER EDGE</td><td class="px-3 py-2 border border-gray-200">吸积盘外边缘半径</td><td class="px-3 py-2 border border-gray-200">10–80 RS</td></tr><tr><td class="px-3 py-2 border border-gray-200 font-mono text-xs">DOPPLER BOOST</td><td class="px-3 py-2 border border-gray-200">多普勒增亮上限</td><td class="px-3 py-2 border border-gray-200">1.0–3.0</td></tr><tr><td class="px-3 py-2 border border-gray-200 font-mono text-xs">BLOOM STRENGTH/RADIUS/THRESHOLD</td><td class="px-3 py-2 border border-gray-200">辉光后处理参数</td><td class="px-3 py-2 border border-gray-200">0–1.5</td></tr><tr><td class="px-3 py-2 border border-gray-200 font-mono text-xs">VIGNETTE / GRAIN / CA</td><td class="px-3 py-2 border border-gray-200">晕影 / 胶片颗粒 / 色差</td><td class="px-3 py-2 border border-gray-200">0–0.15 / 0–0.01</td></tr><tr><td class="px-3 py-2 border border-gray-200 font-mono text-xs">DEBUG VIEW (0–9)</td><td class="px-3 py-2 border border-gray-200">调试可视化模式</td><td class="px-3 py-2 border border-gray-200">0–9</td></tr></tbody></table></div></section><section class="mb-8"><h2 class="text-xl font-semibold text-gray-800 mb-3">技术实现</h2><p class="text-gray-600 leading-relaxed mb-3"> 渲染管线采用全屏四边形（fullscreen quad）+ 片元着色器架构，而非传统 Three.js 几何体渲染。主射线着色器执行逐像素的零测地线积分；结果经 UnrealBloomPass 辉光处理后再由合成着色器施加手动 ACES 色调映射、径向色散、晕影和胶片颗粒效果。整个管线运行在 Half Float HDR 渲染目标上以获得最佳动态范围。 </p><div class="bg-gray-900 rounded-lg p-4 overflow-x-auto"><pre class="text-green-400 text-xs font-mono"><code>Rendering Pipeline:\n  [Ray Fragment Shader] → Geodesic Integration → Disk Emission &amp; Background\n       ↓\n  [RenderPass] → Fullscreen Quad\n       ↓\n  [UnrealBloomPass] → Bloom (strength/radius/threshold)\n       ↓\n  [Composite ShaderPass] → ACES ToneMap + CA + Vignette + Grain\n       ↓\n  Screen Output (HalfFloat HDR RT)</code></pre></div></section><section class="mb-8"><h2 class="text-xl font-semibold text-gray-800 mb-3">快捷键</h2><div class="flex flex-wrap gap-2"><kbd class="px-2 py-1 bg-gray-100 rounded text-xs font-mono">1-4</kbd><span class="text-sm text-gray-600 mr-3">预设视角</span><kbd class="px-2 py-1 bg-gray-100 rounded text-xs font-mono">C</kbd><span class="text-sm text-gray-600 mr-3">电影序列</span><kbd class="px-2 py-1 bg-gray-100 rounded text-xs font-mono">R</kbd><span class="text-sm text-gray-600 mr-3">自动轨道</span><kbd class="px-2 py-1 bg-gray-100 rounded text-xs font-mono">P</kbd><span class="text-sm text-gray-600 mr-3">参数面板</span><kbd class="px-2 py-1 bg-gray-100 rounded text-xs font-mono">H</kbd><span class="text-sm text-gray-600 mr-3">HUD 显示</span></div></section><section class="mb-8"><h2 class="text-xl font-semibold text-gray-800 mb-3">适用场景</h2><ul class="list-disc list-inside text-gray-600 space-y-1 ml-4"><li>天文学教育和科普演示 — 直观理解广义相对论的时空弯曲效应</li><li>科幻视觉参考 — 电影《星际穿越》中 GARGANTUA 黑洞的视觉效果复现</li><li>WebGL / 着色器编程学习 — 实时光线追踪和后处理管线的完整示例</li><li>科学可视化研究 — 探索不同参数下黑洞外观的变化规律</li></ul></section><footer class="mt-12 pt-6 border-t border-gray-200 text-center text-sm text-gray-400"><p>本工具纯浏览器端计算，无需上传任何数据到服务器。渲染性能取决于设备 GPU 能力。</p><p class="mt-1">灵感来源: Christopher Nolan&#39;s Interstellar (2014) · Visualized by Kip S. Thorne</p></footer>',9)])))}]]))}}})}();
